import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.ctLVBroV.js";const g=JSON.parse('{"title":"ResearchHarness","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function n(l,e,h,d,r,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="researchharness" tabindex="-1">ResearchHarness <a class="header-anchor" href="#researchharness" aria-label="Permalink to &quot;ResearchHarness&quot;">​</a></h1><p><a href="https://michakraus.github.io/ResearchHarness/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/docs-dev-blue.svg" alt="Documentation"></a></p><p>ResearchHarness configures AI coding agents for work on research software in Julia. It configures three frontends: Claude Code, OpenCode and oh-my-pi. One set of neutral sources gives each frontend its configuration. One command, <code>harness</code>, installs the configuration and checks it.</p><p>The harness has these features:</p><ul><li><strong>One instruction layer for three frontends.</strong> The agents, skills, rules, commands and instruction files are neutral sources. <code>harness install</code> writes them into the configuration of Claude Code, OpenCode and oh-my-pi.</li><li><strong>Permission settings and their auditor.</strong> One settings template is the policy source of all three frontends. <code>harness settings</code> measures the prompt surface of the Claude Code settings and installs them.</li><li><strong>Guard hooks.</strong> Python hooks refuse unsafe shell commands before they run. Claude Code calls them, and oh-my-pi calls them through an extension. A hook at session start warns when the installed layer is behind its sources.</li><li><strong>Git hooks and CI workflows for Julia packages.</strong> <code>harness githooks</code> and <code>harness workflows</code> install the shared git hooks and GitHub workflows into every repository of a research tree.</li><li><strong>Julia tools.</strong> Scripts for tests, mutation tests and code structure, and JuliaFormatter over every tracked Julia file of the tree.</li><li><strong>Leak checks.</strong> A private profile holds every value that names a person, an institution or a machine. <code>harness leaks</code> and gitleaks keep these values and secrets out of the repository. The pre-push hook and CI run both checks.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>These steps install the harness on macOS. <a href="./setup-macos">Setup on macOS</a> gives the details. First, install the required tools of <a href="#dependencies">Dependencies</a>.</p><ol><li><p>Clone the repository. These steps use the checkout <code>~/Research/Harness</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/michakraus/ResearchHarness.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness</span></span></code></pre></div></li><li><p>Put <code>bin/</code> on the <code>PATH</code>. Also add this line to your shell&#39;s start file, for example <code>~/.zshrc</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Research/Harness/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li><li><p>Make the private profile and the model tables from the examples.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness/examples/profile.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness/profile.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness/examples/models.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness/models.toml</span></span></code></pre></div></li><li><p>Write your values into <code>~/.config/research-harness/profile.toml</code>. Each value replaces the example path <code>/home/example</code> with your home directory, for example <code>/Users/me</code>. The key <code>harness</code> holds the absolute path of the checkout, for example <code>/Users/me/Research/Harness</code>. The key <code>tree_agents</code> names the directory of your tree instructions, and each entry of <code>repository_roots</code> names a directory of your research tree. These directories must exist. With the example values, these commands make them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Environment/Agents/instructions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Packages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Experiments</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Environment/Agents/instructions/research-tree.md</span></span></code></pre></div></li><li><p>Make the two directories and the settings file that the install needs on a new machine. Without the directories, <code>harness install</code> stops with exit 2. Without the file, <code>harness settings install</code> stops with exit 2.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/opencode</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/settings.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/settings.json</span></span></code></pre></div></li><li><p>Install the configuration of each frontend. The first command prints the plan. The second command makes the change.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div></li><li><p>Install the Claude Code settings in the same way.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div></li></ol><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><p>A verb that changes something prints its plan. <code>--apply</code> makes the change. These are the daily verbs:</p><ul><li><code>harness install</code> installs the configuration of each frontend from the sources.</li><li><code>harness test</code> runs the harness&#39;s own test cases.</li><li><code>harness leaks</code> searches the repository and its renders for the leak list of the profile.</li><li><code>harness settings</code> measures, checks and installs the Claude Code settings.</li></ul><p><a href="./harness-command">The <code>harness</code> command</a> describes every verb, the profile and the flags.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>The harness calls the tools below. A tool is required when a verb, a hook, the pre-push gate, CI or an installed git hook calls it. An optional tool serves one frontend or one job; the <code>used for</code> column also says what stops without it. The minimum is the floor that the code checks, that CI pins, that <code>[compat]</code> sets or that a release note names for a feature the code uses; each floor names its source. Where no floor exists, the cell gives the version that the harness is tested with. <a href="./tools">The tools</a> says what each tool does, why the harness needs it, and where the harness calls it.</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">tool</th><th style="text-align:left;">minimum</th><th style="text-align:left;">used for</th></tr></thead><tbody><tr><td style="text-align:left;">Python</td><td style="text-align:left;">≥ 3.11, the check at <code>bin/harness:9</code></td><td style="text-align:left;">runs the <code>harness</code> command, the guard hooks and the pre-push gate</td></tr><tr><td style="text-align:left;">git</td><td style="text-align:left;">tested with 2.54.0</td><td style="text-align:left;">reads and pushes the repositories of the tree, makes the worktrees of Claude Code, and clones the pushed commit for the pre-push gate</td></tr><tr><td style="text-align:left;">gh</td><td style="text-align:left;">tested with 2.102.0</td><td style="text-align:left;">protects the default branch of each repository on GitHub, in <code>harness ci-protection</code></td></tr><tr><td style="text-align:left;">gitleaks</td><td style="text-align:left;">≥ 8.21, the check at <code>.githooks/pre-push:54</code></td><td style="text-align:left;">finds secrets in the commits of a push, in the pre-push gate and in CI</td></tr><tr><td style="text-align:left;">Julia</td><td style="text-align:left;">≥ 1.13, <code>[compat]</code> at <code>Project.toml:22</code></td><td style="text-align:left;">runs the Julia scripts: the formatter, the test runner, the mutation tests, the workflow check and the installed git hooks</td></tr><tr><td style="text-align:left;">ExplicitImports</td><td style="text-align:left;">≥ 1.15, <code>[compat]</code> at <code>Project.toml:16</code></td><td style="text-align:left;">finds the names that a package uses without an explicit import, in the script <code>explicit-imports.jl</code> and the package audit</td></tr><tr><td style="text-align:left;">JSON</td><td style="text-align:left;">≥ 1.10, <code>[compat]</code> at <code>Project.toml:17</code></td><td style="text-align:left;">writes the reports of the test gate and the mutation tests</td></tr><tr><td style="text-align:left;">JuliaFormatter</td><td style="text-align:left;">≥ 2.14, <code>[compat]</code> at <code>Project.toml:18</code></td><td style="text-align:left;">formats Julia code, in <code>harness format</code> and the installed pre-commit hook</td></tr><tr><td style="text-align:left;">JuliaSyntax</td><td style="text-align:left;">≥ 1.0.2, <code>[compat]</code> at <code>Project.toml:19</code></td><td style="text-align:left;">parses Julia code to make the mutants of a mutation test</td></tr><tr><td style="text-align:left;">TestEnv</td><td style="text-align:left;">≥ 1.103.7, <code>[compat]</code> at <code>Project.toml:20</code></td><td style="text-align:left;">runs the tests of a package in its test environment, for the test runner and the mutation tests</td></tr><tr><td style="text-align:left;">YAML</td><td style="text-align:left;">≥ 0.4.17, <code>[compat]</code> at <code>Project.toml:21</code></td><td style="text-align:left;">reads the CI workflows and the frontmatter of the wiki pages</td></tr><tr><td style="text-align:left;">Node.js</td><td style="text-align:left;">≥ 20.16 (20.x), ≥ 22.3, for <code>process.getBuiltinModule</code>, as the API documentation says: <a href="https://nodejs.org/api/process.html#processgetbuiltinmoduleid" target="_blank" rel="noreferrer">https://nodejs.org/api/process.html#processgetbuiltinmoduleid</a></td><td style="text-align:left;">loads the guard extensions of oh-my-pi and OpenCode in the hook probe of <code>harness test</code>, and builds the documentation site with npm and VitePress</td></tr><tr><td style="text-align:left;">shellcheck</td><td style="text-align:left;">tested with 0.11.0</td><td style="text-align:left;">checks the shell scripts, in the pre-push gate and in CI</td></tr><tr><td style="text-align:left;">actionlint</td><td style="text-align:left;">≥ 1.7.12, the CI pin at <code>.github/workflows/test.yml:49</code></td><td style="text-align:left;">checks the GitHub workflow files, in CI</td></tr><tr><td style="text-align:left;">timeout</td><td style="text-align:left;">tested with 9.12</td><td style="text-align:left;">stops <code>fatou lint</code> in the installed pre-commit hook after 60 seconds</td></tr><tr><td style="text-align:left;">fatou</td><td style="text-align:left;">≥ 0.22.0, the CI pin at <code>.github/workflows/julia.yml:45</code></td><td style="text-align:left;">lints the staged Julia files before a commit, and rejects a mutant that uses an undefined name</td></tr><tr><td style="text-align:left;">rsync</td><td style="text-align:left;">tested with 3.5.1</td><td style="text-align:left;">copies a package without its <code>.git</code> directory, for the test runner and the mutation tests</td></tr></tbody></table><h3 id="optional" tabindex="-1">Optional <a class="header-anchor" href="#optional" aria-label="Permalink to &quot;Optional&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">tool</th><th style="text-align:left;">minimum</th><th style="text-align:left;">used for</th></tr></thead><tbody><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;">tested with 2.1.295</td><td style="text-align:left;">reads the layer that <code>harness install</code> writes into <code>~/.claude/</code>, and runs the triggering test of the skills; without it, neither happens</td></tr><tr><td style="text-align:left;">OpenCode</td><td style="text-align:left;">tested with 2.0.26</td><td style="text-align:left;">reads the configuration that <code>harness install</code> writes into <code>~/.config/opencode/</code>; without it, nothing reads that configuration</td></tr><tr><td style="text-align:left;">oh-my-pi</td><td style="text-align:left;">tested with 18.8.6</td><td style="text-align:left;">reads the configuration that <code>harness install</code> writes into <code>~/.omp/agent/</code>; without it, nothing reads that configuration</td></tr><tr><td style="text-align:left;">RTK</td><td style="text-align:left;">tested with 0.51.0</td><td style="text-align:left;">shortens the output of shell commands in OpenCode; without it, the plugin passes each command unchanged</td></tr><tr><td style="text-align:left;">Kaimon</td><td style="text-align:left;">tested with 2.10.0, the <code>version</code> of its app project</td><td style="text-align:left;">gives an agent a Julia session and tools for Julia code; without it, the update job stops with an error, and the agents have no Julia session</td></tr><tr><td style="text-align:left;">jq</td><td style="text-align:left;">tested with 1.7.1</td><td style="text-align:left;">reads the session data for the Claude Code status line; without it, the status line shows no values</td></tr><tr><td style="text-align:left;">juliaup</td><td style="text-align:left;">tested with 1.18.9</td><td style="text-align:left;">updates the Julia releases, in the update job; without it, the job cannot update them</td></tr><tr><td style="text-align:left;">iTerm2</td><td style="text-align:left;">tested with 3.7.3, the <code>CFBundleShortVersionString</code> of the app</td><td style="text-align:left;">shows the state of a Claude Code session in the terminal tab; without it, the hook <code>hooks/cc-status</code> does nothing and exits 0</td></tr></tbody></table><p>The tables leave out the system tools: the POSIX shell utilities, such as <code>awk</code>, <code>sed</code>, <code>grep</code>, <code>ps</code>, <code>kill</code>, <code>id</code> and <code>mktemp</code>; the tools that macOS supplies, <code>launchctl</code>, <code>security</code>, <code>osascript</code>, <code>lsof</code>, <code>pgrep</code> and <code>tar</code>; and the tools of the GitHub runner that the CI jobs call, <code>curl</code>, <code>tar</code> and <code>sha256sum</code>.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The documentation site is <a href="https://michakraus.github.io/ResearchHarness/" target="_blank" rel="noreferrer">https://michakraus.github.io/ResearchHarness/</a>. Its pages are in <code>docs/src/</code>, and VitePress builds them.</p><ul><li><a href="./tutorial">Tutorial: a first session</a>: the words that the other pages use, and one session with Claude Code that shows the harness at work. Start here if you are new to the harness or to coding agents.</li><li><a href="./setup-macos">Setup on macOS</a>: each step of the setup on macOS, and the check that it worked.</li><li><a href="./setup-linux">Setup on Linux</a>: the setup on Linux, which is coming.</li><li><a href="./daily-use">Daily use</a>: a change of a source or of the settings, the drift warning, the leak check, the verbs for the whole research tree and the triggering test of the skills.</li><li><a href="./security">The security model</a>: what each security mechanism stops and does not stop, and the limits of the model.</li><li><a href="./profile">Adapting the profile</a>: each key of the profile and each table of the model tables, and the verbs that read them.</li><li><a href="./harness-command">The <code>harness</code> command</a>: the contract of every verb, the profile and the model tables, the verbs, and the Julia environment.</li><li><a href="./architecture">Architecture</a>: the three layers and the state in <code>~/.claude</code>, the Claude Code layer and its stamp, the neutral vocabulary, the OpenCode and oh-my-pi adapters, and the layout of the repository.</li><li>Components: one page for each kind of component, with a section for each one: <a href="./components/agents">agents</a>, <a href="./components/skills">skills</a>, <a href="./components/commands">commands</a>, <a href="./components/rules">rules</a>, <a href="./components/hooks">guard hooks</a>, <a href="./components/githooks">git hooks and workflows</a>, <a href="./components/scripts">scripts</a>, <a href="./components/adapters">adapters</a>, <a href="./components/harness">the harness command</a> and <a href="./components/other">jobs and configuration</a>.</li><li><a href="./development">Development</a>: the tests, the pre-push hook, the leak checks and CI.</li><li><a href="./tools">The tools</a>: what each dependency does, why the harness needs it, and where the harness calls it.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Code: MIT (<code>LICENSE</code>). Documentation: CC BY 4.0 (<code>LICENSE-docs</code>).</p>`,24)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
